// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Wind".

A fancy air freshener for a marble-tiled bathroom. 
I am referring here to Metamere's interpretation:
"Or it could be wind, as in the verb. :thonk:" 
I went for wind, as in "Excuse me, I think I broke wind."
That's when the air freshener came to mind.

The textures in this scene are procedurally generated from
multiple layers of noise. These same noise layers are used to
create reflections on a sky dome. I've included ambient
occlusion and shadows, but opted out of self-reflection to
keep the performance manageable on mid-range GPUs. Since you
can't see behind the shelf, I didn't add a support, which
basically makes it float. Or you can just imagine a hidden bar.

The stripes and marbling on the surface of the air freshener
should should look like cheap plastic film that has already
come loose. I don't know if that's clear enough.

If it's too grainy for your screen, increase the dpr multiplier to 1.
*/

let theShader, mouseZ = 0, dpr = Math.max(1, 0.5 * window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function mousePressed() {
	mouseZ = 1;
}

function mouseReleased() {
	mouseZ = 0;
}

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(ww, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2502756/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(ww, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
	theShader.setUniform("touch", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);
  theShader.setUniform("pointerCount", mouseZ);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, ww, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 touch;
uniform int pointerCount;
#define mouse (touch/R)
#define P pointerCount
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define MN min(R.x,R.y)
#define N normalize
#define S smoothstep
#define SE(v,s) S(s+1./MN,s-1./MN,v) // smooth edge
#define rot(a) mat2(cos((a)-vec4(0,11,33,0))) // fast 2d rotation
#define lum(a) dot(a,vec3(.21,.71,.07)) // calculates the luminance of the given color
#define sphoff vec3(1,0,0) // the offset of the sphere
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a pseudo random number for a given point (value noise)
float noise(vec2 p) {
	vec2 i=floor(p), f=fract(p), u=f*f*(3.-2.*f);
	float
	a=rnd(i),
	b=rnd(i+vec2(1,0)),
	c=rnd(i+vec2(0,1)),
	d=rnd(i+1.);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
// Returns a pseudo random number for a given point (fractal noise)
float fbm(vec2 p) {
	float t=.0, a=1., h=.0; mat2 m=mat2(1.5,-.6,.6,1.4);
	for (float i=.0; i<5.; i++) {
		t+=a*noise(p*m);
		a*=.5;
		p*=2.*m;
		h+=a;
	}
	return t/h;
}
// Smooth min for scalars
// which can be used as smooth union
// by making b and k negative.
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
// keep track of the material and the glow
float mat=.0, glow=.0;
// Signed distance function of a sphere cut by
// a box, and a cylinder in the core
float planet(vec3 p, float g) {
	vec3 q=abs(p);
	float
	a=length(p)-1., // sphere
	b=max(max(q.x-2.,q.y-.15),q.z-2.), // box
	c=smin(a,-b,-.005), // carve out the box from the sphere
	d=max(b,length(p.xz)-.5); // define a cylinder as long as the box
	glow+=(.0125/(.0125+d*d*80.))*g; // add glow for the cylinder 
	if (g>.0) mat = d<c ? 1. : .0; // determine the material (sphere or glowing cylinder)
	return min(d,c); // return which one is nearer, the sphere or the cylinder
}
// Signed distance function of a box with dimension 's' and corner radius 'r'
float box(vec3 p, vec3 s, float r) {
	p=abs(p)-(s-r);
	return length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z))-r;
}
// Defines the scene you look at
float map(vec3 p, float g) {
	float
	a=planet(p+sphoff, g), // the sphere
	b=box(p+vec3(1,1.5,0),vec3(1.5,.5,1),.005); // the shelf
	if (g>.0) mat = a<b ? mat : 2.; // determine the material (sphere or shelf)
	float
	c=min(a,b), // determines which one is nearer, the sphere or the shelf
	room=-box(p-vec3(0,0,-12),vec3(4,10,14),.01); // defines the walls
	if (g>.0) mat = c < room ? mat : 3.; // determins the material (sphere, shelf or room)
	return min(room,c); // returns which one is nearer, the room, the sphere or the shelf
}
// Returns the normal vector of the 
// surface at the given point
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h,.0)+
		k.yxy*map(p+k.yxy*h,.0)+
		k.yyx*map(p+k.yyx*h,.0)+
		k.xxx*map(p+k.xxx*h,.0)
	);
}
// Returns the amount of shadow
// at the given point and the given
// light position
float shadow(vec3 p, vec3 lp) {
	float shd=1., maxd=length(lp-p);
	vec3 l=normalize(lp-p);
	for (float i=1e-3; i<maxd;) {
		float d=map(p+l*i,.0);
		if (d<1e-3) {
			shd=.0;
			break;
		}
		shd=min(shd,128.*d/i);
		i+=d;
	}
	return shd;
}
// Returns a 2d point on a sphere for a given 3d point
vec2 sm(vec3 p) {
	return .5+vec2(atan(p.x,p.z),atan(p.y,length(p.xz)))/6.28318;
}
// Creates a cloud pattern for a sphere
float pattern(vec3 p) {
	p.xz*=rot(2.);
	vec2 uv=sm(p.zyx*.2);
	return S(1.,.0,abs(p.y))*noise(.5-uv+fbm(uv*20.));
}
// Creates a brick wall pattern
float wall(vec2 p) {
	p.y+=1.75;
	p*=vec2(1,2)*.2;
	p.x+=step(1.,mod(p.y,2.))*.5;
	vec2 id=floor(p);
	p=fract(p);
	return SE(1.,max(abs(p.x+.005),abs(p.y+.01)));
}
// Calculates the ambient occlusion of the scene's objects
float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for (float i=.0; i<5.; i++) {
		float
		h=.01+i*.09,
		d=map(p+h*n,.0);
		occ+=(h-d)*sca;
		sca*=.55;
		if (occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}
// Rotates the camera position
// autonomously or by interacting with the mouse
void cam(inout vec3 p) {
	if (P > 0) {
		p.yz*=rot(sin(-mouse.y*6.3+3.14));
		p.xz*=rot(sin(3.14-mouse.x*6.3)*1.5);	
	} else {
		p.yz*=rot(.42-sin(T*.125)*.42);
		p.xz*=rot(.5*S(1.,-1.,-sin(T*.2)));
	}
}
// Defines the entry function of the shader
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	// defines the camera position .2 units up and 4 - 8 units apart from the sphere, animated over time,
	// only if user does not interact. Does an intro animation starting from far away.
	p=vec3(0,-.2,-mix(4.,8.,P>0?.0:S(.0,1.,1.-T*.025))+(P>0?.0:exp(S(1.,-1.,cos(T*.125))))),
	// defines the direction of the camera which is offsetted more if watched in landscape format
	rd=N(vec3(uv+vec2(R.x>R.y?.2:-.3,0),1.2));
	// do the camera animation
	cam(p); cam(rd);
	// keep track of the distance, the ray has traveled and limit its length
	float dd=.0; const float maxd=18.;
	// perform the raymarching for 400 steps maximum or until it hits a surface or the limit
	for (float i=.0; i<400.; i++) {
		// get the distance to the nearest object
		float d=map(p,1.);
		// stop if at a surface or at the limit
		if (abs(d) < 1e-3 || dd > maxd) break;
		// advance along the ray
		p+=rd*d;
		// record the total length which the ray travelled
		dd+=d;
	}
	// do shading of the objects if the ray has hit any
	if (dd<maxd) {
		// calculate the normal of the surface which the raymarching loop has determined
		vec3 n=norm(p);
		// calculate the ambient occlusion factor of the object
		float ao=calcAO(p,n);
		// handle the different materials
		if (mat==.0) { // the sphere
			// for the rotation animation do rotate the texture, not the object
			vec3 q=p;
			q+=sphoff;
			q.xz*=rot(T*.125);
			q-=sphoff;
			// calculate the texture coordinates for the sphere
			vec2 tx=sm(norm(q));
			// scale the texture
			tx*=.3;
			float t=T*.0; // if you like, you can animate the texture
			// add three layers of noise and soften the poles
			col+=max(.08,S(1.7,.0,(p.y))*fbm(.5+tx+fbm(t*.5-tx*rot(1.5707)*12.+fbm(t+tx*rot(.42)*22.))))*vec3(.1,.3,.9);
			// add highlights
			col=mix(col,vec3(1),lum(col));
			// increase the contrast and darken the texture
			col=tanh(col*col);
			// increase the luminance and also darken according to the calculated ambient occlusion
			col=sqrt(col)*ao;
		} else if (mat==1.) { // the glowing part
			// set to bright white
			col+=1.;
		} else if (mat==2.) { // the shelf
			// map the texture (two layers of noise) to each side (only three are calculated, the others are mirrored
			col+=fbm(p.yz+fbm(p.yz*4.))*abs(n.x);
			col+=fbm(p.xy+fbm(p.xy*4.))*abs(n.z);
			col+=fbm(p.xz+fbm(p.xz*4.))*abs(n.y);
			// some color grading
			col/=1.+exp(-col);
			col=sqrt(vec3(lum(col)));
		} else if (mat==3.) { // the walls
			// map the texture (two layers of noise) to only the walls, not the floor and the ceiling
			col+=mix(.0,.5,fbm(p.yz+fbm(p.yz*4.)))*abs(n.x);
			col+=mix(.0,.2,fbm(p.xy+fbm(p.xy*4.)))*abs(n.z); // make the front and back darker than the sides
			// some color grading
			col=tanh(col*col);
			col=sqrt(col);
			// add the tile joints (use noise to give them a texture, too)
			col=mix(col,vec3(mix(.4,.5,noise(190.*p.xy))),wall(p.xy)*abs(n.z));
			col=mix(col,vec3(mix(.4,.5,noise(190.*p.zy))),wall(p.zy)*abs(n.x));
		} if (mat>1.) { // everything except the sphere
			// calculate the shadow of shelf and walls from a defined light position
			float shd=shadow(p+n*3e-3,vec3(3.3,2.7,-2.95));
			// add (slightly lifted) shadows
			col=mix(vec3(0),col,max(shd,.2));
			// apply the calculated ambient occlusion
			col*=ao;
		}
		// add cubemap reflections (but not to the occluded areas)
		col+=.4*pattern(N(reflect(rd,n)))*ao; 
		// give the sphere some grooves
		if (mat==.0 && abs(n.y)<1.) { 
			vec3 q=p;
			q+=sphoff;
			q.xz*=rot(T*.125);
			col-=.0075*(sin(386.*atan(q.z,q.x)))*S(.4,.7,length(q.xz));
		}
		// add specular reflections
		if (mat==.0 || mat>=2.) {
			col+=.5*pow(clamp(dot(reflect(rd,n),N(vec3(1,2.7,-1))),.0,1.),9.);
		}
	}
	// color grade the whole scene
	col=tanh(col*col*col);
	col=pow(col,vec3(.4545));
	// decrease the luminosity of the scene, just a bit
	col*=.8;
	// vignette (dimensions of the window, normalized)
	vec2 vp=FC/R*2.-1.;
	// widen the frame
	vp*=.95;
	// increase the curvature in the corners
	vp*=vp*vp*vp*vp;
	// calculate the distance to the vignette and soften the transition
	float v=pow(dot(vp,vp),.8);
	// subtract the glow (else it will have artifacts)
	v-=sqrt(glow);
	// just a precaution not to get negative results
	v=max(.0,v);
	// darken the corners (yes absolute black leads to the desired result)
	col=mix(col,vec3(0),v);
	// add the glow to the cylinder at the sphere's core
	col+=vec3(.3,.4,.8)*sqrt(glow);
	// output the final color
	O=vec4(col,1);
}

